#include <iostream>
#include <queue>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 2 || n > 1000) return 1;
    std::priority_queue<int> heap;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        heap.push(value);
    }
    heap.pop();
    std::cout << heap.top() << std::endl;
    return 0;
}
